        for rr, cc in region:
            # Check if 4 is adjacent to this cell
            if (r4, c4) == (rr+1, cc) or (r4, c4) == (rr-1, cc) or \
               (r4, c4) == (rr, cc+1) or (r4, c4) == (rr, cc-1):
